insert into problemas (id, cultivo_id, tipo, nombre, descripcion, orden, fuente, fotos, clasificacion, como_actua, ciclo, ciclo_detalle) values
  (1, 'pitahaya', 'plaga', 'Avispas / murujas', 'Raspan botones florales, flores y frutos.', 1, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Masticador-lamedor', 'Con sus mandíbulas raspan y desgarran la cáscara de botones, flores y frutos, y con la lengua lamen el néctar, el polen y los jugos que brotan de la herida. Las heridas quedan como cicatrices y puerta de entrada de hongos.', '≈ 37 días aprox', 'Huevo a adulto en abejas sin aguijón (Trigona). Dato del género, no medido en pitahaya.'),
  (2, 'pitahaya', 'plaga', 'Hormigas', 'Dañan raíces, flores y frutos; protegen a otras plagas.', 2, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Masticador', 'Con mandíbulas fuertes cortan y mastican raíces, flores y frutos. Además cuidan a insectos chupadores (cochinillas, pulgones) para tomar la melaza que producen, por eso aumentan otras plagas.', '≈ 40 días aprox', 'Huevo a obrera adulta: huevo ≈ 14 días, larva ≈ 14 días y luego pupa. Dato general de hormigas.'),
  (3, 'pitahaya', 'plaga', 'Hormigas arrieras', 'Cortan y cargan tejido; nidos en el suelo.', 3, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Masticador', 'Cortan pedazos de tejido con las mandíbulas y los llevan al nido para cultivar el hongo del que se alimentan; casi no comen el tejido. Por eso funcionan los cebos que la obrera lleva al nido y la aplicación directa en la boca del hormiguero.', '≈ 40 días aprox', 'Huevo a obrera adulta. Dato general de hormigas; la colonia vive años mientras la reina siga viva.'),
  (4, 'pitahaya', 'plaga', 'Chinches', 'Pican tallos, botones y frutos; dejan manchas.', 4, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Picador-chupador', 'Clavan su pico (estilete) en tallos, botones y frutos, inyectan saliva que digiere el tejido y succionan los jugos. La saliva deja manchas, deformaciones y caída de botones.', '≈ 110 días aprox', 'Huevo a adulto de Leptoglossus zonatus (chinche patón de la pitahaya) a unos 25 °C; con más calor el ciclo se acorta.'),
  (5, 'pitahaya', 'plaga', 'Ácaros', 'Manchas y raspado en cladodios y frutos.', 5, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Picador-chupador (quelíceros)', 'No son insectos sino arácnidos. Con sus quelíceros en forma de estilete perforan una por una las células de la cáscara y succionan su contenido; las células vacías se ven como manchas plateadas, bronceadas o raspadas.', '7–10 días aprox', 'Huevo a adulto de Tetranychus a 25–30 °C; con calor y sequía puede bajar a 7 días.'),
  (6, 'pitahaya', 'plaga', 'Babosas y caracoles', 'Mordeduras en brotes tiernos y botones.', 6, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Raspador (rádula)', 'Son moluscos, no insectos. Raspan el tejido tierno con la rádula, una lengua cubierta de dientecillos, y dejan mordeduras irregulares y rastros de baba brillante. Comen de noche y en días húmedos.', '≈ 125 días aprox', 'Huevo a adulto; el huevo tarda unos 17–22 días en eclosionar. Dato de babosas en cultivo de flores.'),
  (7, 'pitahaya', 'plaga', 'Nematodos', 'Raíces con nudos o lesiones; planta débil.', 7, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Picador-chupador (estilete)', 'Gusanos microscópicos del suelo. Con un estilete bucal perforan las células de la raíz, inyectan saliva y succionan su contenido. Unos forman nudos (agallas) y otros dejan lesiones por donde entran hongos como Fusarium.', '21–28 días aprox', 'Huevo a huevo de Meloidogyne (nematodo del nudo) con el suelo a 25–30 °C.'),
  (8, 'pitahaya', 'enfermedad', 'Antracnosis (Colletotrichum) y Alternaria', 'Manchas hundidas en cladodios, flores y frutos.', 8, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Ascomiceto', 'Colletotrichum gloeosporioides (estado sexual Glomerella) y Alternaria son Ascomicetos. Se multiplican por conidias que salpican con la lluvia y entran por heridas o tejido tierno; con humedad alta las manchas crecen rápido.', '≈ 5 días aprox', 'De la infección a los síntomas (incubación) de Colletotrichum gloeosporioides: 4–5 días. Dato de la especie en mango.'),
  (9, 'pitahaya', 'enfermedad', 'Fusarium', 'Pudrición de flor y fruto, pudrición de tallo y raíz; la planta se marchita.', 9, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Deuteromiceto', 'Fusarium se maneja como Deuteromiceto: es un hongo especial que solo responde a determinados ingredientes activos. Vive en el suelo y en restos de cosecha, entra por heridas y raíces dañadas, y se dispersa con el agua de riego, la lluvia y las herramientas.', null, null),
  (10, 'pitahaya', 'enfermedad', 'Prevención de hongos (amplio espectro)', 'Aplicaciones preventivas, sobre todo en épocas de lluvia.', 10, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Amplio espectro (multisitio)', 'Antes de que aparezcan síntomas no se sabe qué hongo atacará, por eso se usan productos multisitio que protegen contra hongos de todas las clases.', null, null),
  (11, 'pitahaya', 'enfermedad', 'Bacteriosis / pudrición blanda', 'Tejido acuoso, blando y con mal olor.', 11, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Bacteria', 'La causan bacterias (Erwinia / Pectobacterium), no hongos. Entran por heridas y deshacen las paredes de las células, por eso el tejido se vuelve acuoso y huele mal.', '≈ 3 días aprox', 'De la infección a los síntomas de pudrición blanda en fruto de pitahaya.'),
  (12, 'pitahaya', 'enfermedad', 'Hongos del suelo (desinfección)', 'Antes de sembrar o en focos de pudrición de raíz.', 12, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Oomiceto + Deuteromiceto + Basidiomiceto', 'En el suelo actúan oomicetos (Pythium, Phytophthora), Fusarium y Rhizoctonia (manejados como Deuteromicetos) y Sclerotium rolfsii (Basidiomiceto, hoy Athelia rolfsii). Como responden a grupos químicos distintos, la desinfección combina productos para las tres clases.', null, null),
  (13, 'pitahaya', 'maleza', 'Malezas en general (no selectivo)', 'Control total de malezas en calles. No tocar la planta.', 13, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'No selectivo (control total)', 'Control de toda la maleza de las calles con herbicidas no selectivos, aplicados dirigidos al suelo y sin mojar los tallos de la pitahaya.', null, null),
  (14, 'pitahaya', 'maleza', 'Malezas de hoja ancha', 'Herbicida selectivo para hoja ancha.', 14, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Hoja ancha', 'Malezas de hoja ancha con nervaduras en red (dicotiledóneas). Compiten por agua y nutrientes y hospedan plagas.', null, null),
  (15, 'pitahaya', 'maleza', 'Gramíneas (pastos)', 'Herbicida selectivo para gramíneas.', 15, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, 'Gramíneas', 'Pastos de hoja angosta con nervaduras paralelas. Cierran las calles, compiten por agua y nutrientes y guardan humedad que favorece hongos.', null, null),
  (16, 'pitahaya', 'nutricion', 'Enraizamiento', 'Esquejes nuevos o raíces débiles.', 16, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, null, null, null, null),
  (17, 'pitahaya', 'nutricion', 'Brotación y floración pareja', 'Estimular y emparejar la brotación y la floración.', 17, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, null, null, null, null),
  (18, 'pitahaya', 'nutricion', 'Estrés de la planta', 'Después de sequía, exceso de lluvia, plagas o podas.', 18, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, null, null, null, null),
  (19, 'pitahaya', 'nutricion', 'Engrose de fruto', 'Mejorar tamaño y llenado del fruto.', 19, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, null, null, null, null),
  (20, 'pitahaya', 'nutricion', 'Suelo ácido (pH bajo)', 'Corregir acidez y aportar calcio y magnesio.', 20, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb, null, null, null, null),
  (21, 'cacao', 'enfermedad', 'Monilia (Moniliophthora roreri)', 'Manchas y bultos en mazorcas jóvenes, luego polvo blanco-crema. Retirar mazorcas enfermas cada semana.', 21, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, 'Basidiomiceto', 'Moniliophthora roreri es un Basidiomiceto. Infecta la mazorca joven en las primeras semanas y sus esporas secas se dispersan con el viento: la clave es proteger la mazorca pequeña y retirar las enfermas.', '3–8 semanas aprox', 'De la infección a los síntomas, según la edad de la mazorca; pocos días después aparecen las esporas crema.'),
  (22, 'cacao', 'enfermedad', 'Escoba de bruja (Moniliophthora perniciosa)', 'Brotes hinchados en forma de escoba y mazorcas deformes. Poda sanitaria y sacar el material enfermo del lote.', 22, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, 'Basidiomiceto', 'Moniliophthora perniciosa es un Basidiomiceto del mismo género que la Monilia (Moniliophthora roreri). Infecta brotes, cojines florales y mazorcas en crecimiento; la escoba verde se seca y, meses después, forma pequeños hongos (setas) que liberan esporas con la lluvia.', '≈ 7–8 meses aprox', 'Infección a escoba verde ≈ 46 días, escoba verde ≈ 39 días y secado ≈ 10 días (Manabí, Ecuador). La escoba seca necesita unas 20–23 semanas más antes de formar las setas que liberan esporas con la lluvia: el ciclo es casi anual.'),
  (23, 'cacao', 'enfermedad', 'Mazorca negra (Phytophthora)', 'Manchas café-negras en la mazorca que avanzan rápido con la lluvia. Mejorar drenaje y regular sombra.', 23, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, 'Oomiceto', 'Phytophthora es un oomiceto: no es un hongo verdadero sino un pseudohongo (reino Stramenopila), con pared de celulosa y sin ergosterol. Produce zoosporas que nadan en el agua y salpican desde el suelo con la lluvia, por eso avanza rápido en épocas lluviosas y con mal drenaje.', '2–3 días aprox', 'De la infección a los primeros síntomas en la mazorca (estudio en Manabí y Esmeraldas, Ecuador); luego la mancha cubre la mazorca en pocos días.'),
  (24, 'cacao', 'plaga', 'Chinche del cacao (Monalonion)', 'Manchas negras hundidas en mazorcas y brotes por picaduras.', 24, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, 'Picador-chupador', 'Pica mazorcas y brotes tiernos con su estilete, inyecta saliva tóxica y succiona los jugos. Alrededor de cada picadura muere el tejido y queda una mancha negra hundida; los brotes atacados se secan.', '≈ 56 días aprox', 'Huevo a adulto: huevo ≈ 15 días y ninfa ≈ 27 días. Dato del género Monalonion en café.'),
  (25, 'cacao', 'plaga', 'Hormigas y comejenes', 'Daño en raíces, brotes y cortes de hojas.', 25, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, 'Masticador', 'Ambos mastican: las hormigas cortan hojas y brotes con las mandíbulas, y los comejenes (termitas) roen raíces, corteza y madera desde sus galerías.', '≈ 40 días aprox', 'Huevo a obrera adulta en hormigas. Dato general de hormigas.'),
  (26, 'cacao', 'maleza', 'Malezas en general (no selectivo)', 'Control en calles sin tocar el tronco ni las hojas del cacao.', 26, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, 'No selectivo (control total)', 'Control de toda la maleza de las calles con herbicidas no selectivos, aplicados dirigidos al suelo y sin tocar el tronco ni las hojas del cacao.', null, null),
  (27, 'cacao', 'nutricion', 'Suelo ácido (pH bajo)', 'Corregir acidez y aportar calcio y magnesio.', 27, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, null, null, null, null),
  (28, 'cacao', 'nutricion', 'Floración y cuajado', 'Apoyar floración y cuajado de mazorcas.', 28, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb, null, null, null, null);
